package com.nigson.experience.engagement;

import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;
import com.nigson.shared.security.PrivateWorkload;
import java.net.URI;
import java.net.http.*;
import java.time.Duration;
import java.util.*;
import java.util.function.Function;
import org.springframework.core.env.Environment;
import com.nigson.shared.observability.WireContext;

/** Fail-closed API-121 client. It never accesses Commerce storage and sends only a proof tuple. */
public final class PurchaseProofClient implements EngagementService.PurchaseProof,EngagementService.MarketValidator {
 private final URI base;private final Function<PrivateWorkload.Route,String> token;private final HttpClient http;
 public PurchaseProofClient(URI base,Function<PrivateWorkload.Route,String> token){this(base,token,HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(2)).build());}
 PurchaseProofClient(URI base,Function<PrivateWorkload.Route,String> token,HttpClient http){this.base=base;this.token=token;this.http=http;}
 public static PurchaseProofClient from(Environment e){String raw=e.getRequiredProperty("NIGSON_COMMERCE_PRIVATE_URL"),issuer=e.getRequiredProperty("NIGSON_OIDC_ISSUER"),client=e.getRequiredProperty("NIGSON_PURCHASE_PROOF_CLIENT_ID"),secret=e.getRequiredProperty("NIGSON_PURCHASE_PROOF_CLIENT_SECRET"),env=e.getRequiredProperty("APP_ENV");URI base=URI.create(raw),token=URI.create(issuer+"/protocol/openid-connect/token");if(!Set.of("http","https").contains(base.getScheme())||base.getHost()==null||base.getRawQuery()!=null||base.getRawFragment()!=null||!Set.of("http","https").contains(token.getScheme())||token.getHost()==null||client.isBlank()||secret.isBlank()||!Set.of("local","test").contains(env)&&(!"https".equals(base.getScheme())||!"https".equals(token.getScheme())))throw new IllegalArgumentException("PURCHASE_PROOF_CONFIGURATION_INVALID");HttpClient clientHttp=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(2)).followRedirects(HttpClient.Redirect.NEVER).build();return new PurchaseProofClient(base,route->{try{String form="grant_type=client_credentials&scope=purchase-proof.read";String authorization=Base64.getEncoder().encodeToString((client+":"+secret).getBytes(java.nio.charset.StandardCharsets.UTF_8));var request=HttpRequest.newBuilder(token).timeout(Duration.ofSeconds(3)).header("Authorization","Basic "+authorization).header("Content-Type","application/x-www-form-urlencoded").POST(HttpRequest.BodyPublishers.ofString(form)).build();var result=clientHttp.send(request,HttpResponse.BodyHandlers.ofByteArray());if(result.statusCode()!=200||result.body().length>8192)return null;var json=EventCodec.JSON.readTree(result.body());return json.path("access_token").asString(null);}catch(Exception failure){return null;}});}
 public boolean active(UUID market){var values=markets();if(values==null)return false;for(var item:values)if(item.path("id").isString()&&market.toString().equalsIgnoreCase(item.path("id").asString()))return true;return false;}
 public UUID resolve(String code){var values=markets();if(values==null)return null;for(var item:values)if(item.path("code").isString()&&code.equals(item.path("code").asString())&&item.path("id").isString())try{return UUID.fromString(item.path("id").asString());}catch(IllegalArgumentException ignored){return null;}return null;}
 private tools.jackson.databind.JsonNode markets(){try{var request=HttpRequest.newBuilder(base.resolve("/api/v1/markets")).timeout(Duration.ofSeconds(5)).header("Accept","application/json").GET().build();var response=http.send(request,HttpResponse.BodyHandlers.ofByteArray());if(response.statusCode()!=200||response.body().length>65536)return null;var json=EventCodec.JSON.readTree(response.body());return json.isArray()&&json.size()<=100?json:null;}catch(Exception unavailable){return null;}}
 public boolean eligible(UUID party,UUID line,UUID product){var route=PrivateWorkload.ROUTES.stream().filter(r->r.api().equals("API-121")&&r.owner().equals("commerce")&&r.client().equals("nigson-experience")).findFirst().orElseThrow(()->new IllegalStateException("PURCHASE_PROOF_ROUTE_MISSING"));String bearer;try{bearer=token.apply(route);}catch(RuntimeException unavailable){throw new Problem.Failure(ProblemCode.PROVIDER_UNAVAILABLE);}if(bearer==null||bearer.isBlank()||bearer.length()>16384)throw new Problem.Failure(ProblemCode.PROVIDER_UNAVAILABLE);var wire=WireContext.current();var body=EventCodec.JSON.writeValueAsBytes(Map.of("partyId",party,"orderLineId",line,"productId",product));var b=HttpRequest.newBuilder(base.resolve("/internal/v1/purchase-proofs")).timeout(Duration.ofSeconds(5)).header("Authorization","Bearer "+bearer).header("Content-Type","application/json").header("Accept","application/json");if(wire!=null)b.header("X-Correlation-ID",wire.correlationId.toString());HttpResponse<byte[]> response;try{response=http.send(b.POST(HttpRequest.BodyPublishers.ofByteArray(body)).build(),HttpResponse.BodyHandlers.ofByteArray());}catch(Exception failure){throw new Problem.Failure(ProblemCode.PROVIDER_UNAVAILABLE);}if(response.statusCode()!=201||response.body().length>4096)throw new Problem.Failure(ProblemCode.PROVIDER_UNAVAILABLE);try{var json=EventCodec.JSON.readTree(response.body());if(!json.propertyNames().equals(Set.of("eligible","reasonCode","revision"))||!json.path("eligible").isBoolean()||!json.path("reasonCode").isString()||!json.path("revision").isIntegralNumber())throw new IllegalArgumentException();return json.path("eligible").asBoolean();}catch(RuntimeException invalid){throw new Problem.Failure(ProblemCode.PROVIDER_UNAVAILABLE);}}
}
